import json
import os
import sys
import subprocess

def load_config(file_path):
    with open(file_path, 'r') as f:
        return json.load(f)

def substitute_command(command, vars):
    for key, value in vars.items():
        command = command.replace(f'{{{{{key}}}}}', value)
    return command

def run_command(command, step_name, dry_run):
    if dry_run:
        print(f'[{step_name}] {command}')
        return 0
    try:
        result = subprocess.run(command, shell=True, capture_output=True, text=True, check=True)
        output = result.stdout
        error = result.stderr
        log_output(step_name, output, error)
        print(f'[{step_name}] {output}{error}')
        return result.returncode
    except subprocess.CalledProcessError as e:
        log_output(step_name, e.stdout, e.stderr)
        print(f'[{step_name}] {e.stdout}{e.stderr}')
        return e.returncode

def log_output(step_name, output, error):
    with open('run.log', 'a') as log_file:
        log_file.write(f'[{step_name}]\n{output}{error}\n')

def main():
    if len(sys.argv) < 2:
        print('Usage: python runner.py <config.json> [--dry-run]')
        sys.exit(1)

    config_path = sys.argv[1]
    dry_run = '--dry-run' in sys.argv

    config = load_config(config_path)
    vars = config.get('vars', {})
    steps = config['steps']

    for step in steps:
        command = substitute_command(step['command'], vars)
        exit_code = run_command(command, step['name'], dry_run)
        if not dry_run and exit_code != 0:
            sys.exit(exit_code)

    if dry_run:
        sys.exit(0)

if __name__ == '__main__':
    main()
